import {SCENARIO,STOPS,STOP,ROADS,ROAD_NODE,RESIDENTS,DEFAULT_DESIGN,LESSON,BUS_STARTS} from './data.js';
import {time,roadPath,evaluate,summary,validateDesign,busPosition,personPosition,along} from './engine.js';
const $=s=>document.querySelector(s),clone=x=>JSON.parse(JSON.stringify(x));
const room=window.BUS_CLASSROOM||null;
const COLORS=['#1264f5','#fa8b24'],KEY=room?.storageKey||'bus-neighbors-v2';
let state={scenario:SCENARIO.id,previousRecords:[],roadUpdated:false,design:clone(DEFAULT_DESIGN),attempts:[],reflections:['','',''],lessonStep:0,introSeen:false,purposeSeen:false},selectedBus=0,selectedPerson=null,selectedChip=null,busSelections=[null,null],adding=false,showTimes=false,editorCollapsed=false,undo=[],mode='design',modal=null,playTime=420,playing=false,speed=3,toastTimer,runSaved=false,comparisonIndex=0,modalTrigger=null,suppressNextClick=false;
let syncError=false,classroomFocus=null;
try{
 const saved=JSON.parse(localStorage.getItem(KEY));
 if(saved&&validateDesign(saved.design)){
  state={...state,...saved,scenario:SCENARIO.id};
  const valid=(saved.attempts||[]).filter(a=>validateDesign(a.design)&&Array.isArray(a.results));
  const old=valid.filter(a=>a.scenario!==SCENARIO.id);
  state.attempts=valid.filter(a=>a.scenario===SCENARIO.id);
  if(saved.scenario!==SCENARIO.id){
   state.roadUpdated=true;
   if(old.length||(saved.reflections||[]).some(Boolean)){
    state.previousRecords=[...(saved.previousRecords||[]),{scenario:saved.scenario||old[0]?.scenario||'previous',attempts:old,reflections:saved.reflections||[]}];
    state.reflections=['','',''];
   }
  }
 }
}catch{}
if(!state.purposeSeen&&(!room||room.preview||['lobby','active'].includes(room.control?.status)))modal='purpose';
else if(!state.introSeen&&(!room||room.preview||room.control?.status==='active'))modal='start-guide';
let computed=evaluate(state.design);
function notifyRoom(){room?.sync?.({state:clone(state),mode:activityMode()});}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));notifyRoom();}catch{toast('이 기기에서 저장 공간을 사용할 수 없습니다. 결과를 내보내 주세요.');}}
function activityMode(){if(room&&!room.preview&&room.control?.status!=='active')return ({lobby:'waiting',paused:'paused',ended:'ended'})[room.control?.status]||'waiting';return modal==='reflection'?'reflection':modal==='results'||modal==='record-person'||(mode==='run'&&playTime>=600)?'results':mode;}
function classroomChrome(){if(!room)return '';const c=room.control||{},stage=LESSON[Math.max(0,Math.min(6,c.phase||0))]?.[0]||'수업';const bar=`<div class="classroom-bar"><b>수업 ${room.code}</b><span class="room-stage">${(c.phase||0)+1}. ${stage}</span><span class="room-message">${escape(c.message||'선생님 화면의 안내에 따라 활동하세요.')}</span><span class="room-team">${escape(room.teamName)}${syncError?' · <i class="sync-error">저장 연결 확인</i>':''}</span></div>`;if(room.preview)return bar;const locked=['lobby','paused','ended'].includes(c.status)&&!(c.status==='lobby'&&modal==='purpose')?`<div class="classroom-lock"><div class="lock-card" role="dialog" aria-modal="true" aria-label="수업 진행 상태" tabindex="-1"><span>${c.status==='lobby'?'⌛':c.status==='paused'?'Ⅱ':'✓'}</span><h2>${c.status==='lobby'?'곧 수업이 시작됩니다':c.status==='paused'?'잠시 멈췄습니다':'수업이 끝났습니다'}</h2><p>${escape(c.status==='lobby'?'선생님이 수업을 시작하면 자동으로 활동 화면이 열립니다.':c.status==='paused'?'선생님이 다시 시작할 때까지 모둠에서 지금까지의 선택을 이야기해 보세요.':'작성한 기록은 이 기기에 남아 있습니다. 선생님이 대시보드에서 수신한 결과를 확인합니다.')}</p></div></div>`:'';return bar+locked;}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const portrait=(p,extra='')=>`<div class="portrait ${extra}" role="img" aria-label="${p.name}의 모습" style="--px:${(p.portrait%4)*100/3}%;--py:${Math.floor(p.portrait/4)*50}%"></div>`;
function busSVG(i,cls='bus-mini'){return `<svg class="${cls}" viewBox="0 0 72 40" aria-hidden="true"><defs><linearGradient id="body${i}" x2="0" y2="1"><stop stop-color="${i?'#ffb75e':'#55a4ff'}"/><stop offset="1" stop-color="${COLORS[i]}"/></linearGradient></defs><path d="M5 8 12 3H64L68 9 65 30H5Z" fill="${i?'#ce6512':'#124f9e'}"/><rect x="4" y="8" width="59" height="23" rx="4" fill="url(#body${i})"/><path d="M9 3H62L65 8H4Z" fill="${i?'#ffd08b':'#86c3ff'}"/><rect x="8" y="11" width="49" height="11" rx="2" fill="#173a57"/><path d="M19 11V22M30 11V22M41 11V22M51 11V22" stroke="#a4d5f4" stroke-width="2"/><path d="M63 10 66 9 64 23 61 23Z" fill="#abdcf6"/><rect x="6" y="25" width="54" height="2" fill="#fff" opacity=".45"/><circle cx="16" cy="32" r="5" fill="#162b48"/><circle cx="51" cy="32" r="5" fill="#162b48"/><circle cx="16" cy="32" r="2" fill="#b7c4d7"/><circle cx="51" cy="32" r="2" fill="#b7c4d7"/><rect x="59" y="25" width="3" height="3" fill="#fff0ae"/></svg>`;}
function statusHTML(r){return `<span class="status ${r.status}">${r.status==='ontime'?'✓':r.status==='late'?'△':'×'} ${r.arrival==null?'이동 불가':`${time(r.arrival)} 도착${r.late?` · ${r.late}분 지각`:''}`}</span>`;}
function routeText(r){return r.rides?.length?r.rides.map(x=>`${x.busId+1}호차 ${STOP[x.from].name} → ${STOP[x.to].name}`).join(' / '):r.arrival!=null?'도보 이동':'이용 경로 없음';}
function mutate(fn,nextSelected=selectedChip){if(mode!=='design')return;undo.push({design:clone(state.design),selectedBus,selectedChip,busSelections:[...busSelections],adding});if(undo.length>40)undo.shift();fn();selectedChip=nextSelected;busSelections[selectedBus]=selectedChip;computed=evaluate(state.design);persist();render();}
function toast(message){clearTimeout(toastTimer);$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);toastTimer=setTimeout(()=>el.remove(),3000);}
function applyClassroomLock(){
 const locked=room&&!room.preview&&['lobby','paused','ended'].includes(room.control?.status);
 if(locked&&!classroomFocus&&document.activeElement?.closest?.('.app-header,.workspace,.bottom-bar,.modal-shade'))classroomFocus=document.activeElement;
 document.querySelectorAll('.app-header,.workspace,.bottom-bar').forEach(el=>el.inert=Boolean(locked));
 if($('.modal-shade'))$('.modal-shade').inert=Boolean(locked&&!(room.control?.status==='lobby'&&modal==='purpose'));
 if(locked)$('.lock-card')?.focus({preventScroll:true});
 else if(classroomFocus){if(classroomFocus.isConnected)classroomFocus.focus({preventScroll:true});classroomFocus=null;}
}
function render(){$('#app').innerHTML=`<div id="classroom-chrome">${classroomChrome()}</div>
 <header class="app-header"><div class="brand"><svg class="brand-icon" viewBox="0 0 32 40" aria-hidden="true"><rect x="3" y="1" width="26" height="34" rx="7" fill="currentColor"/><rect x="7" y="10" width="18" height="13" rx="2" fill="white"/><rect x="11" y="5" width="10" height="2" rx="1" fill="white"/><circle cx="9" cy="29" r="2" fill="white"/><circle cx="23" cy="29" r="2" fill="white"/><path d="M7 33v5m18-5v5" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg><h1>이 버스는 누구를 지나치는가</h1></div><p class="tagline">버스 두 대로 주민들의 아침을 연결해요.</p>
 <nav class="top-nav" aria-label="활동 단계"><button class="step ${mode==='design'?'active':''}" data-action="design"><i>1</i>노선 설계</button><span class="nav-chevron">›</span><button class="step ${mode==='run'?'active':''}" data-action="run"><i>2</i>운행</button><span class="nav-chevron">›</span><button class="step ${modal==='results'?'active':''}" data-action="results"><i>3</i>비교·정리</button></nav><button class="help-button" data-action="lesson">수업 안내</button></header>
 <main class="workspace"><section class="map-panel proportionate-map ${selectedChip!=null?'editing-order':''} ${editorCollapsed?'editor-collapsed':''}" aria-label="버스 노선을 편집하는 마을 지도"><div class="map-toolbar">
 <div class="bus-switcher" role="group" aria-label="편집할 버스 선택">${[0,1].map(i=>`<button class="bus-tab ${i?'orange':''} ${selectedBus===i?'selected':''}" data-action="bus" data-id="${i}" aria-pressed="${selectedBus===i}">${busSVG(i)}${i+1}호차${state.design.lowBus===i?'<small>· 저상</small>':''}</button>`).join('')}</div>
 ${mode==='design'?`<button class="settings-button" data-action="settings" aria-haspopup="dialog"><b>운행 기본 설정</b><small>1호차 ${time(state.design.buses[0].departure)} · 2호차 ${time(state.design.buses[1].departure)} · 저상 ${state.design.lowBus+1}호차</small></button>`:''}${mode==='run'?`<div class="map-clock"><b id="clock">${time(playTime)}</b><p>운행 시각</p></div>`:''}<button class="legend-chip" data-action="road-times" aria-pressed="${showTimes}">${showTimes?'구간 시간 숨기기':'도로 이동 시간 보기'}</button>${mode==='design'?`<button class="editor-collapse" data-action="collapse-editor" aria-expanded="${!editorCollapsed}">${editorCollapsed?'편집 열기':'편집 접기'}</button>`:''}</div>
 <div class="map-viewport"><div class="map-scene"><img class="map-art" src="./assets/town-map.png" alt="강과 다리로 연결된 언덕마을, 아파트, 학교, 마을 버스터미널, 병원과 공장 지도" draggable="false"><svg class="map-svg" viewBox="0 0 1000 760" preserveAspectRatio="none" aria-hidden="true">${mapSVG()}</svg><div id="stops">${STOPS.map(s=>stopHTML(s)).join('')}</div><div id="people">${peopleHTML()}</div><div id="live-state"></div></div>${adding&&mode==='design'&&state.design.buses[selectedBus].route.length<STOPS.length?`<div class="map-hint">${insertionName()} 뒤에 추가할 새 정류장을 누르세요.</div>`:''}</div>
 ${mode==='design'?editorHTML():playbackHTML()}</section>
 </main>
 <footer class="bottom-bar"><div class="bottom-note"><div>${mode==='run'?'버스와 주민의 시간을 함께 따라가 보세요.':'노선을 바꾸면, 주민의 이동이 달라집니다.'}<small>교육용 가상 자료 · 혼잡·정원 제한 생략 · ${room?'교사 화면과 이 기기에 자동 저장':'이 기기에 자동 저장'}</small></div></div><button id="attempt-count" class="secondary" data-action="results" ${state.attempts.length||state.previousRecords.length?'':'hidden'}>시도 기록 ${state.attempts.length}</button><button class="primary" data-action="${mode==='run'?'finish':'run'}">${mode==='run'?'결과 확인하기 →':'▶ 운행해 보기'}</button></footer>${modal?modalHTML():''}`;bind();applyClassroomLock();if(mode==='run')updateAnimation();notifyRoom();}
function mapSVG(){let html=ROADS.map(r=>`<polyline points="${r.points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#f5f8fa" stroke-width="5" opacity=".42" stroke-linecap="round"/>`).join('');
 [1-selectedBus,selectedBus].forEach(i=>{const route=state.design.buses[i].route;for(let j=1;j<route.length;j++){const points=roadPath(route[j-1],route[j]).points.map(p=>p.join(',')).join(' ');html+=`<polyline class="bus-line" points="${points}" stroke="white" stroke-width="${i?12:10}"/><polyline class="bus-line" points="${points}" stroke="${COLORS[i]}" stroke-width="${i?7:5}" opacity=".96"/>`;}});
 if(selectedPerson){const r=computed.results.find(r=>r.id===selectedPerson);r.rides.forEach(ride=>{for(let j=1;j<ride.stops.length;j++){const pts=roadPath(ride.stops[j-1],ride.stops[j]).points.map(p=>p.join(',')).join(' ');html+=`<polyline class="bus-line" points="${pts}" stroke="#ffe577" stroke-width="3.5" stroke-dasharray="8 5"/>`;}});}
 if(showTimes)ROADS.forEach(r=>{const p=along(r.points,.5);html+=`<text class="road-time" x="${p[0]}" y="${p[1]-10}" text-anchor="middle">${r.minutes}분</text>`;});
 return html+[0,1].map(i=>{const pos=busPosition(computed.schedules[i],mode==='run'?playTime:state.design.buses[i].departure)?.point;return pos?`<g id="vehicle-${i}" class="vehicle" transform="translate(${pos[0]-25},${pos[1]-28})"><svg width="55" height="34" viewBox="0 0 72 40">${busSVG(i).replace(/^<svg[^>]*>|<\/svg>$/g,'')}</svg><text x="29" y="-2" text-anchor="middle" font-size="12" fill="white" stroke="#173858" stroke-width="3" paint-order="stroke" font-weight="800">${i+1}호차${state.design.lowBus===i?' ♿':''}</text></g>`:'';}).join('');}
function stopHTML(s){const indexes=state.design.buses.map(b=>b.route.indexOf(s.id)),own=indexes[selectedBus],served=indexes.some(n=>n>=0),p=RESIDENTS.find(p=>p.id===selectedPerson);return `<button class="stop ${served?'served':''} ${own>=0?'selected-route':''} ${mode==='design'&&selectedChip!=null&&own===selectedChip?'insertion-point':''} ${['N','E'].includes(s.id)?'minor':''} ${p?.access[s.id]!=null?'origin':''} ${p?.egress[s.id]!=null?'destination':''}" style="left:${s.x/10}%;top:${s.y/7.6}%;--stop-color:${COLORS[own>=0?selectedBus:indexes[0]>=0?0:1]}" data-action="stop" data-id="${s.id}" aria-label="${s.name} 정류장${own>=0?`, ${selectedBus+1}호차 ${own+1}번째`:`, ${selectedBus+1}호차 ${insertionName()} 뒤에 추가`}"><span class="stop-label">${s.name}</span><span class="stop-dot">${own>=0?own+1:''}</span></button>`;}
function peopleHTML(){if(mode!=='run')return '';return RESIDENTS.map(p=>{const r=computed.results.find(r=>r.id===p.id),pos=personPosition(p,r,computed.schedules,playTime);return `<div id="person-${p.id}" class="people-marker portrait" title="${p.name}" style="left:${pos.point[0]/10}%;top:${pos.point[1]/7.6}%;--px:${p.portrait%4*100/3}%;--py:${Math.floor(p.portrait/4)*50}%"></div>`;}).join('');}
function insertionIndex(){const r=state.design.buses[selectedBus].route;return selectedChip!=null&&selectedChip<r.length?selectedChip:r.length-1;}
function insertionName(){return STOP[state.design.buses[selectedBus].route[insertionIndex()]].name;}
function editorHTML(){const b=state.design.buses[selectedBus],s=computed.schedules[selectedBus];return `<section class="route-editor" aria-label="${selectedBus+1}호차 노선 편집"><div class="editor-heading">${busSVG(selectedBus)}<h2>${selectedBus+1}호차</h2><span class="edit-tag">${STOP[BUS_STARTS[selectedBus]].name} 출발</span><button class="undo" data-action="undo" ${undo.length?'':'disabled'}>↶ 되돌리기</button></div><div class="editor-meta"><span>${s.cycle?`왕복 ${s.cycle}분 · 다음 출발 ${b.departure+s.cycle<600?time(b.departure+s.cycle):'10:00 이후'}`:'정류장을 2곳 이상 연결해 주세요.'}</span><button data-action="timetable">시간표·운행 규칙</button></div>${state.roadUpdated?'<div class="road-update"><p>학교·병원·공장 앞 갈림길을 연결했어요. 현재 설계로 다시 운행해 주세요. 이전 결과는 시도 기록에서 따로 볼 수 있어요.</p><button data-action="dismiss-road-update">확인</button></div>':''}<div class="route-list" aria-label="정류장 순서">${b.route.map((id,i)=>`${i?'<span class="route-arrow">→</span>':''}<div class="route-chip ${i===0?'fixed':''} ${selectedChip===i?'active':''}" draggable="false" ${i?`data-drag="${i}" data-action="chip" data-index="${i}" tabindex="0" role="button" aria-label="${i+1}번째 ${STOP[id].name}, 선택하여 이 뒤에 추가하거나 순서 변경"`:`data-action="chip" data-index="0" tabindex="0" role="button" aria-label="고정 기점 ${STOP[id].name}, 선택하여 이 뒤에 추가"`}><span>${i===0?'출발 · ':''}${STOP[id].name}</span>${i?`<button data-action="remove" data-index="${i}" aria-label="${STOP[id].name} 노선에서 삭제">×</button>`:'<small>고정</small>'}</div>`).join('')}</div>${selectedChip!=null?`<div class="route-tools"><b>${STOP[b.route[selectedChip]]?.name}</b><button data-action="move" data-dir="-1" ${selectedChip<=1?'disabled':''}>← 앞으로</button><button data-action="move" data-dir="1" ${selectedChip===0||selectedChip===b.route.length-1?'disabled':''}>뒤로 →</button><span>${selectedChip===0?'출발점은 고정이며, 그 뒤에 추가할 수 있어요.':'끌어서도 순서를 바꿀 수 있어요.'}</span></div>`:''}${b.route.length<STOPS.length?`<div class="insertion-guide" aria-live="polite"><b>${insertionName()} 뒤에 추가</b><span>지도에서 새 정류장을 누르세요.</span>${insertionIndex()<b.route.length-1?'<button data-action="append-end">맨 끝에 추가하기</button>':''}</div>`:'<p class="insertion-guide">모든 정류장이 포함되어 있어요. 정류장을 선택해 순서를 바꿀 수 있습니다.</p>'}<div class="editor-controls"><button class="add-stop ${adding?'on':''}" data-action="add-stop" ${b.route.length===STOPS.length?'disabled':''}>＋ 정류장 추가</button></div></section>`;}
function detailHTML(){const p=RESIDENTS.find(p=>p.id===selectedPerson),r=computed.results.find(r=>r.id===p.id);return `<div class="sidebar-head"><button class="back" data-action="back">← 주민 12명 모두 보기</button><div class="detail-profile">${portrait(p)}<div><h2>${p.name}의 아침</h2><p>${p.role}</p></div></div>${statusHTML(r)}</div><div class="detail-scroll"><p class="story">“${p.story}”</p><dl class="facts"><dt>출발 → 도착</dt><dd>${p.home} → ${p.destination}</dd><dt>나갈 수 있는 때</dt><dd>${time(p.ready)}부터</dd><dt>도착 시한</dt><dd>${time(p.deadline)}까지</dd><dt>보행 조건</dt><dd>${p.walk}</dd><dt>차량 조건</dt><dd>${p.low?'저상버스 필요':'일반·저상버스 모두 가능'}</dd></dl><h3 class="detail-heading">${mode==='run'?'이용':'예상'} 경로 ${r.duration!=null?`· 총 ${r.duration}분`:''}</h3>${itineraryHTML(p,r)}${r.status!=='ontime'?`<p class="reason">${r.reason}</p>`:''}<h3 class="detail-heading">갈 수 있는 정류장</h3><p class="route-status">${Object.entries(p.access).map(([id,w])=>`${STOP[id].name}까지 ${w}분`).join(' · ')}<br>하차 후 ${p.destination}까지 ${Object.values(p.egress)[0]}분</p></div>`;}
function itineraryHTML(p,r){if(r.arrival==null)return '<p class="route-status">현재 설계에서는 연결되는 이동 경로를 찾지 못했어요.</p>';let rows=[`<strong>${time(p.ready)} 집에서 출발</strong><p>${STOP[r.origin].name}까지 ${r.walkIn}분 이동</p>`];r.rides.forEach((ride,i)=>{rows.push(`<strong>${time(i?r.rides[i-1].alight:p.ready+r.walkIn)} ${STOP[ride.from].name} ${i?'환승':'정류장 도착'}</strong><p>${i?`환승 이동 2분 포함 ${ride.board-r.rides[i-1].alight}분`:`${r.initialWait}분 대기`}</p>`);rows.push(`<strong style="color:${COLORS[ride.busId]}">${time(ride.board)} ${ride.busId+1}호차 탑승 → ${time(ride.alight)} 하차</strong><p>${ride.stops.map(id=>STOP[id].name).join(' → ')} · ${ride.alight-ride.board}분</p>`);});rows.push(`<strong>${time(r.arrival)} ${p.destination} 도착</strong><p>하차 후 ${r.walkOut}분 이동</p>`);return `<div class="itinerary">${rows.map(s=>`<div class="journey-step">${s}</div>`).join('')}</div>`;}
function playbackHTML(){return `<section class="playback-panel"><div class="playback-row"><h3>우리 노선의 아침</h3><button class="secondary" data-action="pause" id="pause">${playing?'Ⅱ 일시정지':'▶ 계속 보기'}</button><button class="secondary" data-action="speed" id="speed">빠르게 ${speed===3?'1':speed===9?'3':'10'}×</button></div><input id="timeline" type="range" min="420" max="600" step="0.1" value="${playTime}" aria-label="운행 시각 탐색"><div class="playback-labels"><span>07:00</span><span>08:00</span><span>09:00</span><span>10:00</span></div><p class="simulation-note">1×에서 실제 1초는 마을의 3분 · 시각을 밀어 이동 장면을 살펴보세요.</p></section>`;}
function openModal(kind){modalTrigger=document.activeElement?.dataset?.action;playing=false;modal=kind;render();$('.close-modal')?.focus();}
function closeModal(){if(modal==='purpose'){state.purposeSeen=true;modal=!state.introSeen&&(!room||room.preview||room.control?.status==='active')?'start-guide':null;persist();render();if(modal)$('.close-modal')?.focus();else if(modalTrigger)document.querySelector(`[data-action="${modalTrigger}"]`)?.focus();return;}const wasStartGuide=modal==='start-guide';modal=null;if(wasStartGuide){state.introSeen=true;persist();}render();if(modalTrigger)document.querySelector(`[data-action="${modalTrigger}"]`)?.focus();}
function delta(first,next){if(first.arrival==null&&next.arrival!=null)return {text:'새롭게 이동 가능',kind:'better'};if(first.arrival!=null&&next.arrival==null)return {text:'이동 가능 → 불가',kind:'worse'};if(first.arrival==null)return {text:'여전히 이동 불가',kind:'same'};const d=next.duration-first.duration;return {text:d>0?`${d}분 더 걸림`:d<0?`${-d}분 줄어듦`:'이동 시간 같음',kind:d>0?'worse':d<0?'better':'same'};}
function metricsHTML(results){const s=summary(results);return `<div class="metrics"><div class="metric"><strong>${s.ontime}</strong><span>명 정시 도착</span></div><div class="metric"><strong>${s.late}</strong><span>명 지각</span></div><div class="metric"><strong>${s.impossible}</strong><span>명 이동 불가</span></div><div class="metric"><strong>${s.average??'—'}</strong><span>분 평균 이동</span><p class="save-note">이동 가능한 ${s.count}명만 계산 · 불가 ${s.impossible}명 제외</p></div></div>`;}
function previousRecordsHTML(){return state.previousRecords.length?`<details class="previous-records"><summary>도로 수정 전 기록 보기</summary><p class="save-note">원래 결과와 답변을 그대로 보관했습니다. 도로 조건이 달라 새 시도와 비교하지 않습니다.</p>${state.previousRecords.map(group=>`${group.attempts.map((a,i)=>`<h3>이전 ${i+1}차 시도</h3><div class="table-wrap"><table><thead><tr><th>주민</th><th>도착 결과</th><th>이용 경로</th></tr></thead><tbody>${RESIDENTS.map((p,j)=>`<tr><th>${p.name}</th><td>${statusHTML(a.results[j])}</td><td>${routeText(a.results[j])}</td></tr>`).join('')}</tbody></table></div>`).join('')}${group.reflections.map((answer,i)=>`<p class="old-answer"><b>${i+1}. ${QUESTIONS[i]}</b><br>${escape(answer||'미작성')}</p>`).join('')}`).join('')}</details>`:'';}
function resultsHTML(){const selected=state.attempts[Math.min(comparisonIndex,state.attempts.length-1)],first=state.attempts[0];if(!selected)return `${previousRecordsHTML()}<p class="story">아직 저장된 운행이 없어요. 주민의 조건을 살펴보고 노선을 설계한 뒤 ‘운행해 보기’를 눌러 주세요. 운행 결과를 확인하면 첫 시도가 저장됩니다.</p><div class="modal-actions">${state.previousRecords.length?'<button class="secondary" data-action="export">이전 기록 내보내기</button>':''}<button class="primary" data-action="close">설계로 돌아가기</button></div>`;
 const compare=comparisonIndex>0,newly=selected.results.filter((r,i)=>r.arrival!=null&&first.results[i].arrival==null),slower=selected.results.filter((r,i)=>r.arrival!=null&&first.results[i].arrival!=null&&r.duration>first.results[i].duration),lost=selected.results.filter((r,i)=>r.arrival==null&&first.results[i].arrival!=null),name=r=>RESIDENTS.find(p=>p.id===r.id).name;
 return `${previousRecordsHTML()}<div class="attempt-select"><label for="attempt">살펴볼 시도</label><select id="attempt">${state.attempts.map((a,i)=>`<option value="${i}" ${comparisonIndex===i?'selected':''}>${i+1}차 시도${i===0?' · 첫 설계':''}</option>`).join('')}</select><span class="save-note">${compare?'첫 시도와 같은 도시·주민 조건으로 비교':'첫 시도가 저장되었어요. 이 결과를 기준으로 비교합니다.'}</span></div>${metricsHTML(selected.results)}${compare?`<div class="comparison-notes"><p><b>새롭게 이동할 수 있는 사람</b><br>${newly.length?newly.map(name).join(', '):'없음'}</p><p><b>더 오래 걸리거나 이동이 어려워진 사람</b><br>${slower.length?slower.map(name).join(', ')+' · 이동 시간 증가':'이동 시간이 늘어난 주민 없음'}${lost.length?'<br>'+lost.map(name).join(', ')+' · 이동 불가로 변경':''}</p></div>${selected.results.every((r,i)=>r.arrival!=null&&(first.results[i].arrival==null||r.duration<=first.results[i].duration))?'<p class="story">모든 주민이 이동할 수 있고, 기존에 이동하던 누구의 시간도 늘어나지 않았어요. 이런 개선도 설계로 얻을 수 있는 결과입니다.</p>':''}`:''}
 <div class="table-wrap"><table><thead><tr><th>주민 · 목적지</th>${compare?'<th>첫 시도</th>':''}<th>${compare?'수정 시도':'도착 결과'}</th><th>실제 이용 경로${compare?' · 변화':''}</th></tr></thead><tbody>${RESIDENTS.map((p,i)=>{const r=selected.results[i],d=delta(first.results[i],r);return `<tr><td><button class="table-name" data-action="record-person" data-id="${p.id}">${p.name}</button><div class="table-route">${p.home} → ${p.destination}<br>${time(p.deadline)}까지</div></td>${compare?`<td>${statusHTML(first.results[i])}<div class="table-route">${first.results[i].duration!=null?`총 ${first.results[i].duration}분`:''}</div></td>`:''}<td>${statusHTML(r)}<div class="table-route">${r.duration!=null?`총 ${r.duration}분`:''}</div></td><td><div class="table-route">${routeText(r)}</div>${compare?`<div class="change ${d.kind}">${d.text}</div>`:''}${r.status!=='ontime'?`<details class="table-route"><summary>이유 보기</summary>${r.reason}</details>`:''}</td></tr>`;}).join('')}</tbody></table></div><div class="modal-actions"><button class="secondary" data-action="export">기록 내보내기</button>${state.attempts.length===1?'<span class="result-next">놓친 주민을 살펴보고, 둘의 역할을 바꿔 다시 설계해 보세요.</span><button class="primary" data-action="redesign">다시 설계하기 →</button>':'<button class="secondary" data-action="redesign">다시 설계하기</button><button class="primary" data-action="reflection">모둠 생각 정리 →</button>'}</div>`;}
const QUESTIONS=['우리의 선택으로 이동이 가능해진 사람은 누구인가?','그 대신 누가 더 기다리거나 돌아가게 되었는가?','정류장이 있다는 것과 실제로 목적지에 갈 수 있다는 것은 어떻게 다른가?'];
function reflectionProgress(){const count=state.reflections.filter(x=>x.trim()).length;return `${count}/3 작성${count===3?' 완료':''} · ${room&&!room.preview?(syncError?'이 기기에 보관 중 · 교사 연결을 확인해 주세요.':'이 기기에 자동 저장하며, 선생님 화면으로 자동 전달합니다.'):'이 기기에 자동 저장됩니다.'}`;}
function updateReflectionProgress(){const el=$('#reflection-progress');if(el)el.textContent=reflectionProgress();}
function lessonHTML(reflection=false){return `${reflection?'':`<div class="lesson-timeline">${LESSON.map(([title,min],i)=>`<div class="lesson-stage"><b>${min}분</b>${i+1}. ${title}</div>`).join('')}</div><p class="story">우리 모둠은 두 대의 버스를 운영합니다. 인쇄 자료에서 주민의 아침을 살펴보고, 노선을 정해 운행해 보세요. 첫 결과에서 놓친 주민을 살핀 뒤 같은 조건으로 다시 설계합니다.</p><h3 class="detail-heading">노선은 이렇게 바꿔요</h3><ol class="rules"><li>1호차는 아파트, 2호차는 언덕마을에서 출발하며 기점은 고정됩니다.</li><li>지도 위에서 버스를 고르고 정류장을 운행 순서대로 누릅니다. 목록의 ×로 삭제하고, 정류장 이름을 누른 뒤 ‘앞으로·뒤로’로 순서를 바꿉니다.</li><li>첫 출발 시각과 저상버스 배치를 정합니다. 다음 출발은 왕복 시간에 맞춰 자동으로 계산됩니다.</li><li>인쇄 자료의 주민 조건과 노선을 비교한 뒤 ‘운행해 보기’를 누릅니다. 결과를 확인하면 이 기기에 시도가 저장됩니다.</li></ol><button class="secondary" data-action="timetable">가상 자료와 운행 규칙 보기</button>`}
 ${reflection?`<p class="story">저장한 결과에서 주민의 이름과 시간을 근거로 이야기해 보세요. 누구도 더 불편해지지 않았다면 그 사실도 그대로 적어 주세요.</p>${QUESTIONS.map((q,i)=>`<label class="reflection-question" for="reflection-${i}">${i+1}. ${q}</label><textarea class="reflection-text" id="reflection-${i}" data-reflection="${i}" placeholder="주민의 이름과 우리 모둠이 발견한 변화를 적어 주세요.">${escape(state.reflections[i]||'')}</textarea>`).join('')}<p id="reflection-progress" class="reflection-progress" role="status">${reflectionProgress()}</p><div class="concepts"><article class="concept"><h3>공간 불평등</h3><p>같은 도시에서도 사는 위치와 이동 경로에 따라 학교·병원·일자리에 도달하기 쉬운 정도가 달랐나요?</p></article><article class="concept"><h3>실질적인 기회</h3><p>정류장이 있어도 출발 시각, 보행 조건, 차량 종류가 맞지 않으면 실제로 이용할 기회가 제한될 수 있어요.</p></article><article class="concept"><h3>공공서비스 분배</h3><p>한정된 두 대를 어디에, 언제 배치했나요? 더 많은 주민의 시간과 접근이 어려운 주민의 필요를 어떻게 함께 고려했나요?</p></article></div><div class="modal-actions"><button class="secondary" data-action="results">결과 다시 보기</button><button class="secondary" data-action="export">기록 파일 내려받기</button><button class="primary" data-action="close">작성 마치기</button></div>`:'<div class="modal-actions"><button class="primary" data-action="close">노선 설계 시작하기 →</button></div>'}`;}
function purposeHTML(){return `<div class="purpose-scene" aria-hidden="true"><span>학교로</span><span>일터로</span><span>병원으로</span><div>${busSVG(0)}${busSVG(1)}</div></div><p class="purpose-lead">같은 마을에 살아도,<br><strong>모두가 같은 조건으로 이동하지는 않습니다.</strong></p><p class="purpose-copy">학교에 가야 하는 학생, 출근해야 하는 주민, 병원 진료를 받아야 하는 주민이 있어요. 집에서 나올 수 있는 시각도, 걸을 수 있는 거리도, 탈 수 있는 버스도 다릅니다.</p><div class="purpose-mission"><b>여러분은 두 대의 버스를 맡은 노선 설계자입니다.</b><p>노선과 첫 출발 시각, 저상버스 배치를 정해 주민들의 아침을 연결해 보세요.</p></div><p class="purpose-copy">우리의 선택으로 <b>누가 갈 수 있게 되었는지</b>, <b>누가 더 기다리거나 돌아가게 되었는지</b> 확인하고 다시 설계합니다. 선택이 주민들의 실제 이동 기회를 어떻게 바꾸는지 알아보는 활동입니다.</p><p class="purpose-pair">둘이 함께 생각하세요. 한 명은 지도를 조작하고, 한 명은 주민 자료를 살펴봅니다. 다시 설계할 때 역할을 바꿔요.</p><div class="modal-actions"><button class="primary" data-action="close">알겠어요 →</button></div>`;}
function settingsHTML(){return `<form id="operating-settings"><section class="departure-settings"><h3>각 버스는 몇 시에 처음 출발하나요?</h3><p>주민이 집에서 나올 수 있는 시각과 도착 시한을 함께 확인하세요.</p><div class="settings-buses">${state.design.buses.map((b,i)=>`<label class="settings-bus bus-${i}"><span class="settings-bus-title">${busSVG(i)}<span><b>${i+1}호차</b><small>${STOP[BUS_STARTS[i]].name}에서 출발</small></span></span><span class="settings-field-name">첫 출발 시각</span><input type="time" id="departure-${i}" aria-label="${i+1}호차 첫 출발 시각" min="07:00" max="09:59" required value="${time(b.departure)}"></label>`).join('')}</div><p class="settings-hint">07:00~09:59 중 선택 · 이후 출발은 노선의 왕복 시간에 맞춰 자동으로 반복됩니다.</p></section><section class="low-floor-settings"><h3>저상버스 한 대는 어느 노선에 배치하나요?</h3><p>저상버스가 필요한 주민은 일반 버스에 탈 수 없습니다. 그 주민이 이용할 노선을 확인하세요.</p><div class="low-floor-options">${[0,1].map(i=>`<label><input type="radio" name="lowBus" value="${i}" ${state.design.lowBus===i?'checked':''} required><span><b>${i+1}호차를 저상버스로</b><small>${STOP[BUS_STARTS[i]].name} 출발 노선</small></span></label>`).join('')}</div></section><div class="modal-actions"><button type="button" class="secondary" data-action="close">취소</button><button class="primary" type="submit">설정 적용하기</button></div></form>`;}
function startGuideHTML(){return `<p class="start-guide-copy">선생님이 나눠 준 인쇄 자료에서 주민의 출발지·목적지·도착 시한·보행 조건을 확인하세요.</p><div class="start-buses">${state.design.buses.map((b,i)=>`<article>${busSVG(i)}<div><b>${i+1}호차 · ${STOP[BUS_STARTS[i]].name} 출발</b><span>${time(b.departure)} 첫 출발${state.design.lowBus===i?' · 저상버스':''}</span></div></article>`).join('')}</div><ol class="start-steps"><li><b>버스를 고릅니다.</b><span>지도 위 1호차 또는 2호차를 누르세요.</span></li><li><b>정류장을 연결합니다.</b><span>지도에서 누르는 순서대로 연결돼요. 중간에 넣으려면 기존 정류장을 먼저 선택하세요.</span></li><li><b>두 버스의 운행 기본 설정을 확인합니다.</b><span>지도 위 ‘운행 기본 설정’에서 버스별 첫 출발 시각을 정하고, 저상버스 한 대를 어느 노선에 배치할지 고르세요.</span></li><li><b>운행하고 다시 설계합니다.</b><span>결과에서 놓친 주민과 늘어난 이동 시간을 확인하세요.</span></li></ol><p class="start-guide-note">1호차는 아파트, 2호차는 언덕마을이 고정 기점입니다.</p><div class="modal-actions"><button class="primary" data-action="close">노선 설계 시작하기 →</button></div>`;}
function timetableHTML(){return `<p class="story">노선에 지정한 정류장에서만 승하차합니다. 정류장 사이에서는 연결된 도로 중 이동 시간이 가장 짧은 길을 따라갑니다. 지나가기만 하는 정류장에는 서지 않아요.</p><div class="comparison-notes">${computed.schedules.map((s,i)=>`<div class="metric"><h3 style="color:${COLORS[i]}">${i+1}호차 ${state.design.lowBus===i?'· 저상버스':''}</h3><p class="rules">${state.design.buses[i].route.map(id=>STOP[id].name).join(' → ')||'노선 없음'}</p><p class="rules">왕복 ${s.cycle}분 · 기점 출발 ${s.departures.map(time).join(', ')||'운행 없음'}</p><details class="rules"><summary>모든 정류장 시각 보기</summary><div class="table-wrap"><table><thead><tr><th>정류장</th><th>도착</th><th>출발</th></tr></thead><tbody>${s.visits.filter(v=>v.arr<=600).map(v=>`<tr><td>${STOP[v.stop].name}</td><td>${time(v.arr)}</td><td>${v.dep<600?time(v.dep):'운행 종료'}</td></tr>`).join('')}</tbody></table></div></details></div>`).join('')}</div><h3 class="detail-heading">시간을 계산하는 약속</h3><ul class="rules"><li>07:00–10:00 동안 버스별 한 대가 한 왕복 노선을 반복 운행합니다. 첫 출발 시각은 기점에서 문을 닫고 떠나는 시각입니다.</li><li>중간 정류장에 1분 정차합니다. 양쪽 종점은 정차 1분 + 회차 2분 뒤 반대 방향으로 출발합니다.</li><li>왕복 시간 = 도로 이동 시간의 두 배 + 중간 정류장 정차의 두 배 + 양 종점 6분. 한 대의 버스가 이보다 자주 출발할 수는 없습니다.</li><li>집에서 정류장까지의 이동, 대기, 버스 탑승, 최대 1회 환승, 하차 후 이동을 모두 더합니다. 모든 주민은 집에서 나갈 수 있는 가장 이른 시각에 출발합니다.</li><li>환승은 같은 정류장에서 2분 이상 필요합니다. 출발 시각까지 정류장에 도착해야 탈 수 있고, 저상버스가 필요한 주민은 모든 탑승 구간이 저상버스여야 합니다.</li><li>조건에 맞는 경로 중 목적지에 가장 먼저 도착하는 경로를 선택합니다. 10:00까지 도착하는 연결편이 없으면 ‘이동 불가’입니다. 시한과 같은 시각에 도착하면 정시 도착입니다.</li><li>차량 혼잡·정원 초과·신호 대기 변동·교통 체증은 생략합니다. 그림 속의 작은 주차 차량은 배경이며 운행 차량은 1·2호차 두 대입니다.</li><li>주민 조건·보행·도로 시간은 모두 교육용 가상 자료입니다. 보행 가능한 접근로는 주민별로 정해져 있으며 실제 지역이나 인물을 나타내지 않습니다.</li></ul><h3 class="detail-heading">도로별 편도 이동 시간</h3><div class="table-wrap"><table><thead><tr><th>도로 연결</th><th>이동 시간</th></tr></thead><tbody>${ROADS.map(r=>`<tr><td>${ROAD_NODE[r.a].name} ↔ ${ROAD_NODE[r.b].name}</td><td>${r.minutes}분</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="primary" data-action="close">지도 돌아가기</button></div>`;}
function modalHTML(){let title,subtitle,body;if(modal==='purpose'){title='이 버스는 누구의 아침을 연결할까요?';subtitle='활동을 시작하기 전에 · 우리가 이 활동을 하는 이유';body=purposeHTML();}else if(modal==='settings'){title='운행 기본 설정';subtitle='두 버스의 첫 출발 시각과 저상버스 배치를 함께 정하세요.';body=settingsHTML();}else if(modal==='results'){title='우리의 선택은 무엇을 바꿨을까?';subtitle='주민 한 사람씩, 첫 시도와 수정 시도의 이동을 비교해요.';body=resultsHTML();}else if(modal==='reflection'){title='결과에서 사회를 읽어 보기';subtitle='마지막 7분 · 우리 모둠의 생각';body=lessonHTML(true);}else if(modal==='record-person'){const a=state.attempts[comparisonIndex],p=RESIDENTS.find(p=>p.id===selectedPerson),r=a.results.find(r=>r.id===selectedPerson);title=`${p.name} · ${comparisonIndex+1}차 시도 이동 기록`;subtitle=`${p.home} → ${p.destination} · ${time(p.deadline)}까지`;body=`${statusHTML(r)}${itineraryHTML(p,r)}<p class="reason">${r.reason}</p><div class="modal-actions"><button class="primary" data-action="results">비교표로 돌아가기</button></div>`;}else if(modal==='timetable'){title='두 대가 실제로 움직이는 시간';subtitle='가상 자료 · 시간표와 운행 규칙';body=timetableHTML();}else if(modal==='start-guide'){title='인쇄 자료를 보고 노선을 만드세요';subtitle='활동을 시작하기 전에 네 가지만 확인하세요.';body=startGuideHTML();}else{title='45분, 우리 모둠의 노선 설계';subtitle='통합사회 · 구체적인 주민의 아침에서 시작합니다.';body='<div class="purpose-reopen"><button class="secondary" data-action="purpose">이 활동을 하는 이유 다시 보기</button></div>'+lessonHTML();}return `<div class="modal-shade"><section class="modal ${modal==='start-guide'?'start-guide-modal':modal==='settings'?'settings-modal':modal==='purpose'?'purpose-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="close-modal" data-action="close" aria-label="닫기">×</button></header><div class="modal-body">${body}</div></section></div>`;}
function updateAnimation(){const note=$('.map-clock p');if(note)note.textContent=playTime>=600?'운행 종료 · 10:00':playing?'시간표에 맞춰 운행 중':'일시정지';const c=$('#clock');if(c)c.textContent=time(playTime);const slider=$('#timeline');if(slider&&document.activeElement!==slider)slider.value=playTime;for(let i=0;i<2;i++){const pos=busPosition(computed.schedules[i],playTime);if(pos)$(`#vehicle-${i}`)?.setAttribute('transform',`translate(${pos.point[0]-25},${pos.point[1]-28})`);}
 RESIDENTS.forEach((p,i)=>{const r=computed.results[i],pos=personPosition(p,r,computed.schedules,playTime),el=$(`#person-${p.id}`);if(el){el.style.left=pos.point[0]/10+'%';el.style.top=pos.point[1]/7.6+'%';el.title=`${p.name} · ${pos.state}`;el.style.opacity=pos.state.includes('탑승')&&p.id!==selectedPerson?'.35':'1';}if(selectedPerson===p.id&&$('#live-state'))$('#live-state').innerHTML=`<div class="live-state">${p.name} · ${pos.state}</div>`;});
 if(playTime>=600){playing=false;recordRun();$('#pause')&&( $('#pause').textContent='↶ 처음부터');}}
let lastFrame=0;function frame(now){if(playing&&mode==='run'&&!modal){playTime=Math.min(600,playTime+Math.min(.15,(now-lastFrame)/1000)*speed);updateAnimation();}lastFrame=now;requestAnimationFrame(frame);}
function recordRun(){if(mode!=='run'||runSaved)return;runSaved=true;state.attempts.push({scenario:SCENARIO.id,design:clone(state.design),results:clone(computed.results),savedAt:new Date().toISOString()});persist();const counter=$('#attempt-count');if(counter){counter.hidden=false;counter.textContent=`시도 기록 ${state.attempts.length}`;}}
function saveRun(){playing=false;playTime=600;updateAnimation();recordRun();comparisonIndex=state.attempts.length-1;openModal('results');}
function exportRecord(){const data={title:'이 버스는 누구를 지나치는가',scenario:'교육용 가상 자료 · 오전 07:00–10:00',previousRecords:clone(state.previousRecords),attempts:state.attempts.map((a,i)=>({attempt:i+1,design:a.design,residents:RESIDENTS.map((p,j)=>({name:p.name,destination:p.destination,deadline:time(p.deadline),...a.results[j],arrivalTime:time(a.results[j].arrival),route:routeText(a.results[j])}))})),reflection:QUESTIONS.map((q,i)=>({question:q,answer:state.reflections[i]}))};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));a.href=url;a.download='우리-모둠-버스-활동기록.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('시도별 결과와 모둠 생각을 파일로 내보냈어요.');}
function moveChip(from,to){const r=state.design.buses[selectedBus].route;if(from===to||from<1||to<1||to>=r.length)return;mutate(()=>{const [id]=r.splice(from,1);r.splice(to,0,id);},to);}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();if(suppressNextClick){suppressNextClick=false;return;}action(el.dataset.action,el.dataset);}));document.querySelectorAll('[data-action=chip]:not([data-drag])').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action('chip',el.dataset);}}));$('#operating-settings')?.addEventListener('submit',e=>{e.preventDefault();if(mode!=='design')return;const form=e.currentTarget;if(!form.reportValidity())return;const departures=[0,1].map(i=>{const [h,m]=$('#departure-'+i).value.split(':').map(Number);return h*60+m;}),lowBus=Number(form.querySelector('input[name="lowBus"]:checked')?.value);if(departures.some(t=>!Number.isInteger(t)||t<420||t>599)||![0,1].includes(lowBus)){toast('출발 시각과 저상버스 배치를 확인해 주세요.');return;}const changed=departures.some((t,i)=>t!==state.design.buses[i].departure)||lowBus!==state.design.lowBus;modal=null;if(changed)mutate(()=>{departures.forEach((t,i)=>state.design.buses[i].departure=t);state.design.lowBus=lowBus;});else render();$('[data-action=settings]')?.focus({preventScroll:true});});
 document.querySelectorAll('[data-drag]').forEach(el=>{let drag=null;el.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,from:Number(el.dataset.drag),moved:false};el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>8){drag.moved=true;el.style.opacity='.5';el.style.cursor='grabbing';}});el.addEventListener('pointerup',e=>{if(!drag)return;const current=drag;drag=null;el.style.opacity='';el.style.cursor='';if(current.moved){suppressNextClick=true;setTimeout(()=>suppressNextClick=false,150);const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drag]');if(target)moveChip(current.from,Number(target.dataset.drag));}});el.addEventListener('pointercancel',()=>{drag=null;el.style.opacity='';});el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',el.dataset.drag);e.dataTransfer.effectAllowed='move';});el.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';});el.addEventListener('drop',e=>{e.preventDefault();const from=Number(e.dataTransfer.getData('text/plain'));if(Number.isInteger(from))moveChip(from,Number(el.dataset.drag));});el.addEventListener('keydown',e=>{if(e.target!==el)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();selectedChip=Number(el.dataset.drag);render();}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveChip(Number(el.dataset.drag),Number(el.dataset.drag)+(e.key==='ArrowLeft'?-1:1));}});});
 $('#timeline')?.addEventListener('input',e=>{playing=false;playTime=Number(e.target.value);$('#pause').textContent='▶ 계속 보기';updateAnimation();});$('#attempt')?.addEventListener('change',e=>{comparisonIndex=Number(e.target.value);render();});document.querySelectorAll('[data-reflection]').forEach(el=>el.addEventListener('input',e=>{state.reflections[Number(el.dataset.reflection)]=e.target.value;persist();updateReflectionProgress();}));
 $('.modal')?.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button,select,textarea,a[href],input,summary')].filter(el=>!el.disabled&&el.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}});
}
function action(name,d={}){switch(name){case 'purpose':openModal('purpose');break;case 'settings':if(mode==='design')openModal('settings');break;case 'dismiss-road-update':state.roadUpdated=false;persist();render();break;case 'bus':busSelections[selectedBus]=selectedChip;selectedBus=Number(d.id);selectedChip=busSelections[selectedBus];adding=false;render();break;case 'resident':selectedPerson=d.id;render();break;case 'back':selectedPerson=null;render();break;case 'collapse-editor':editorCollapsed=!editorCollapsed;if(editorCollapsed)adding=false;render();break;case 'stop':if(mode!=='design'){toast('노선 설계 단계에서 정류장을 변경할 수 있어요.');return;}{const r=state.design.buses[selectedBus].route;if(r.includes(d.id)){const index=r.indexOf(d.id);selectedChip=index;adding=false;editorCollapsed=false;render();}else{const insertAt=insertionIndex()+1;mutate(()=>r.splice(insertAt,0,d.id),insertAt);}}break;case 'chip':selectedChip=Number(d.index);adding=false;render();break;case 'remove':{const index=Number(d.index),r=state.design.buses[selectedBus].route;if(index>0&&index<r.length){const next=selectedChip==null?null:selectedChip>=index?Math.max(0,selectedChip-1):selectedChip;mutate(()=>r.splice(index,1),next);}}break;case 'move':moveChip(selectedChip,selectedChip+Number(d.dir));break;case 'add-stop':adding=!adding;render();break;case 'append-end':selectedChip=state.design.buses[selectedBus].route.length-1;adding=true;render();break;case 'undo':if(undo.length){const previous=undo.pop();state.design=previous.design;selectedBus=previous.selectedBus;selectedChip=previous.selectedChip;busSelections=previous.busSelections;adding=previous.adding;computed=evaluate(state.design);persist();render();}break;case 'road-times':showTimes=!showTimes;render();break;case 'design':case 'redesign':mode='design';playing=false;modal=null;selectedChip=null;adding=false;render();break;case 'run':if(mode==='run'){modal=null;playing=true;render();return;}if(state.design.buses.some(b=>b.route.length<2)){toast('버스마다 정류장을 2곳 이상 연결해 주세요.');return;}mode='run';playing=true;playTime=420;adding=false;runSaved=false;modal=null;render();break;case 'pause':if(playTime>=600)playTime=420;playing=!playing;$('#pause').textContent=playing?'Ⅱ 일시정지':'▶ 계속 보기';updateAnimation();break;case 'speed':speed=speed===3?9:speed===9?30:3;$('#speed').textContent=`빠르게 ${speed===3?'1':speed===9?'3':'10'}×`;break;case 'finish':saveRun();break;case 'results':if(mode==='run'&&!runSaved){saveRun();break;}if(modal!=='record-person')comparisonIndex=state.attempts.length-1;openModal('results');break;case 'record-person':selectedPerson=d.id;openModal('record-person');break;case 'lesson':case 'timetable':case 'reflection':openModal(name);break;case 'close':closeModal();break;case 'export':exportRecord();break;}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();for(const tool of [{name:'read_bus_design',title:'버스 설계와 예상 이동 결과 읽기',description:'현재 기기의 버스 두 대 노선·출발·저상 배치와 주민별 실제 계산 결과를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({design:clone(state.design),results:clone(computed.results),savedAttempts:state.attempts.length})},{name:'configure_bus_design',title:'버스 노선과 시간표 변경',description:'지도에서 편집하는 것과 같은 설계 변경을 적용합니다. 시도를 저장하거나 운행을 완료하지 않습니다. 버스 두 대, 정류장 ID, 07:00–09:59 출발을 검사합니다.',inputSchema:{type:'object',properties:{buses:{type:'array',minItems:2,maxItems:2,items:{type:'object',properties:{route:{type:'array',items:{type:'string',enum:STOPS.map(s=>s.id)},uniqueItems:true,maxItems:8},departure:{type:'integer',minimum:420,maximum:599}},required:['route','departure'],additionalProperties:false}},lowBus:{type:'integer',enum:[0,1]}},required:['buses','lowBus'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(mode!=='design')throw Error('노선 설계 단계에서만 변경할 수 있습니다.');if(!validateDesign(input))throw Error('유효하지 않은 버스 설계입니다.');mutate(()=>state.design=clone(input));return {design:clone(state.design),results:clone(computed.results)};}}]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
if(room){
 let previousStatus=room.control?.status,resumeAfterPause=false;
 function refreshClassroom(){const chrome=$('#classroom-chrome');if(chrome)chrome.innerHTML=classroomChrome();applyClassroomLock();}
 window.addEventListener('classroom-state',()=>{
  const status=room.control?.status;
  if(status!=='active'&&!room.preview){if(previousStatus!==status)resumeAfterPause=status==='paused'&&playing;playing=false;updateAnimation();}
  else if(previousStatus==='paused'&&resumeAfterPause&&mode==='run'&&!modal){playing=true;resumeAfterPause=false;updateAnimation();}
  previousStatus=status;
  refreshClassroom();
  if(status==='active'&&!modal&&mode==='design'&&(!state.purposeSeen||!state.introSeen)){openModal(state.purposeSeen?'start-guide':'purpose');}
  notifyRoom();
 });
 window.addEventListener('classroom-sync-status',event=>{syncError=!event.detail;refreshClassroom();updateReflectionProgress();});
}
render();if(modal==='purpose')$('.close-modal')?.focus();if(state.roadUpdated)persist();requestAnimationFrame(frame);registerTools();
